{
  "name": "opencode-free-router",
  "version": "0.1.3",
  "description": "opencode plugin: always run on the best free model available, ranked by LMArena and Artificial Analysis, sticky per session, with automatic failover.",
  "private": true,
  "type": "module",
  "license": "BSD-2-Clause",
  "homepage": "https://github.com/lettland/opencode-free-router#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/lettland/opencode-free-router.git"
  },
  "bugs": {
    "url": "https://github.com/lettland/opencode-free-router/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "free-models",
    "llm-router",
    "lmarena",
    "openrouter",
    "bb"
  ],
  "engines": {
    "node": ">=22.18"
  },
  "scripts": {
    "test": "node --test test/*.test.ts",
    "test:coverage": "mkdir -p coverage && node --test --experimental-test-coverage --test-coverage-include='src/**' --test-coverage-include-all --test-reporter=spec --test-reporter-destination=stdout --test-reporter=lcov --test-reporter-destination=coverage/lcov.info test/*.test.ts",
    "check": "tsc",
    "lint:sh": "shellcheck scripts/*.sh bin/opencode-free",
    "e2e": "./scripts/e2e-failover.sh"
  },
  "devDependencies": {
    "@opencode/plugin": "2.0.32",
    "@types/node": "^22.20.4",
    "typescript": "^7.0.2"
  }
}
